//! # zkDTVM Proof
//!
//! A library of types and functions for zkDTVM proofs.
#![allow(missing_docs)]

use std::{
    fmt::{self, Debug, Display, Formatter},
    fs::File,
    path::Path,
};

use anyhow::{Context, Result};
use dt_core_executor::DTReduceProof;
use dt_primitives::{io::DTPublicValues, SCField};
use dt_prover::{
    CoreSC, DTProvingKey, Groth16Bn254Proof, HashableKey, InnerSC, PlonkBn254Proof, RootSC,
};
use dt_stark::sumcheck::{
    config::MlPcsOpeningProof,
    keys::SCStarkVerifyingKey,
    proof::{SCShardCommitment, SCShardOpenedValues, SCShardProof, SumcheckProof},
};
use hashbrown::HashMap;
use p3_field::{AbstractField, PrimeField};
use pcs::basefold::{basefold_pcs::BasefoldInputProof, sumcheck::SumcheckInstanceProof};
use serde::{Deserialize, Serialize};
use strum_macros::{EnumDiscriminants, EnumTryAs};

type InnerOpeningProof = MlPcsOpeningProof<InnerSC>;
type RootOpeningProof = MlPcsOpeningProof<RootSC>;

/// A proof generated by the zkDTVM RISC-V zkVM.
#[derive(Clone, Serialize, Deserialize, EnumDiscriminants, EnumTryAs)]
#[strum_discriminants(derive(Default, Hash, PartialOrd, Ord))]
#[strum_discriminants(name(DTProofMode))]
pub enum DTProof {
    /// A proof generated by the core proof mode.
    ///
    /// The proof size scales linearly with the number of cycles.
    #[strum_discriminants(default)]
    Core(Vec<SCShardProof<CoreSC>>),
    /// A proof generated by the compress proof mode.
    ///
    /// The proof size is constant, regardless of the number of cycles. In the ext5
    /// KoalaBear configuration this is the final root_shrink proof whose PCS Merkle
    /// commitments use SHA256.
    Compressed(Box<DTReduceProof<RootSC>>),
    /// A proof generated by the shrink proof mode.
    ///
    /// A recursive shrink proof that still uses the inner Poseidon2 PCS.
    Shrink(Box<DTReduceProof<InnerSC>>),
    /// A proof generated by the Plonk proof mode.
    Plonk(PlonkBn254Proof),
    /// A proof generated by the Groth16 proof mode.
    Groth16(Groth16Bn254Proof),
}

impl Display for DTProof {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        match self {
            DTProof::Core(_) => write!(f, "Core"),
            DTProof::Compressed(_) => write!(f, "Compressed"),
            DTProof::Shrink(_) => write!(f, "Shrink"),
            DTProof::Plonk(_) => write!(f, "Plonk"),
            DTProof::Groth16(_) => write!(f, "Groth16"),
        }
    }
}

/// A proof generated by the zkDTVM RISC-V zkVM bundled together with the public values and the
/// version.
#[derive(Clone, Serialize, Deserialize)]
pub struct DTProofWithPublicValues {
    /// The raw proof generated by the zkDTVM RISC-V zkVM.
    pub proof: DTProof,
    /// The public values generated by the zkDTVM RISC-V zkVM.
    pub public_values: DTPublicValues,
    /// The version of the zkDTVM RISC-V zkVM (not necessary but useful for detecting version
    /// mismatches).
    pub dt_version: String,
    /// The integrity proof generated by the TEE server.
    pub tee_proof: Option<Vec<u8>>,
}

/// The proof generated by the prover network.
///
/// Since [`bincode`] is not self describing, it cannot handle "nullable" optional values.
#[derive(Clone, Serialize, Deserialize)]
pub struct ProofFromNetwork {
    pub proof: DTProof,
    pub public_values: DTPublicValues,
    pub dt_version: String,
}

impl From<ProofFromNetwork> for DTProofWithPublicValues {
    fn from(value: ProofFromNetwork) -> Self {
        Self {
            proof: value.proof,
            public_values: value.public_values,
            dt_version: value.dt_version,
            tee_proof: None,
        }
    }
}

impl DTProofWithPublicValues {
    /// Creates a new [`DTProofWithPublicValues`] from the proof, public values, and zkDTVM version.
    ///
    /// If the [`tee`] feature is enabled, the proof field is set to none.
    pub(crate) const fn new(
        proof: DTProof,
        public_values: DTPublicValues,
        dt_version: String,
    ) -> Self {
        Self { proof, public_values, dt_version, tee_proof: None }
    }

    /// Saves the proof to a path.
    pub fn save(&self, path: impl AsRef<Path>) -> Result<()> {
        bincode::serialize_into(
            File::create(path.as_ref()).with_context(|| {
                format!("failed to create file for saving proof: {}", path.as_ref().display())
            })?,
            self,
        )
        .map_err(Into::into)
    }

    /// Loads a proof from a path.
    pub fn load(path: impl AsRef<Path>) -> Result<Self> {
        bincode::deserialize_from(File::open(path.as_ref()).with_context(|| {
            format!("failed to open file for loading proof: {}", path.as_ref().display())
        })?)
        .map_err(Into::into)
    }

    /// The proof in the byte encoding the onchain verifiers accepts for [`DTProofMode::Groth16`]
    /// and [`DTProofMode::Plonk`] proofs.
    ///
    /// # Details
    /// The bytes consist of the first four bytes of Groth16/Plonk vkey hash followed by the encoded
    /// proof, in a form optimized for onchain verification.
    #[must_use]
    pub fn bytes(&self) -> Vec<u8> {
        match &self.proof {
            DTProof::Plonk(plonk_proof) => {
                // If the proof is empty, then this is a mock proof. The mock zkDTVM verifier
                // expects an empty byte array for verification, so return an empty byte array.
                if plonk_proof.encoded_proof.is_empty() {
                    return Vec::new();
                }

                let proof_bytes =
                    hex::decode(&plonk_proof.encoded_proof).expect("Invalid Plonk proof");

                if let Some(tee_proof) = &self.tee_proof {
                    return [
                        tee_proof.clone(),
                        plonk_proof.plonk_vkey_hash[..4].to_vec(),
                        proof_bytes,
                    ]
                    .concat();
                }

                [plonk_proof.plonk_vkey_hash[..4].to_vec(), proof_bytes].concat()
            }
            DTProof::Groth16(groth16_proof) => {
                // If the proof is empty, then this is a mock proof. The mock zkDTVM verifier
                // expects an empty byte array for verification, so return an empty byte array.
                if groth16_proof.encoded_proof.is_empty() {
                    return Vec::new();
                }

                let proof_bytes =
                    hex::decode(&groth16_proof.encoded_proof).expect("Invalid Groth16 proof");

                if let Some(tee_proof) = &self.tee_proof {
                    return [
                        tee_proof.clone(),
                        groth16_proof.groth16_vkey_hash[..4].to_vec(),
                        proof_bytes,
                    ]
                    .concat();
                }

                [groth16_proof.groth16_vkey_hash[..4].to_vec(), proof_bytes].concat()
            }
            proof => panic!(
                "Proof type {proof} is not supported for onchain verification. \
                Only Plonk and Groth16 proofs are verifiable onchain"
            ),
        }
    }

    /// Creates a mock proof for the specified proof mode from the public values.
    ///
    /// # Example
    /// ```rust,no_run
    /// use dt_sdk::{
    ///     DTProofMode, DTProofWithPublicValues, DTStdin, Prover, ProverClient, DT_CIRCUIT_VERSION,
    /// };
    ///
    /// let elf = &[1, 2, 3];
    /// let stdin = DTStdin::new();
    ///
    /// let client = ProverClient::builder().cpu().build();
    /// let (pk, vk) = client.setup(elf);
    /// let (public_values, _) = client.execute(&pk.elf, &stdin).run().unwrap();
    ///
    /// // Create a mock Plonk proof.
    /// let mock_proof = DTProofWithPublicValues::create_mock_proof(
    ///     &pk,
    ///     public_values,
    ///     DTProofMode::Plonk,
    ///     DT_CIRCUIT_VERSION,
    /// );
    /// ```
    #[must_use]
    pub fn create_mock_proof(
        pk: &DTProvingKey,
        public_values: DTPublicValues,
        mode: DTProofMode,
        dt_version: &str,
    ) -> Self {
        let dt_version = dt_version.to_string();
        match mode {
            DTProofMode::Core => DTProofWithPublicValues {
                proof: DTProof::Core(vec![]),
                public_values,
                dt_version,

                tee_proof: None,
            },
            DTProofMode::Compressed => {
                let shard_proof = SCShardProof {
                    commitment: SCShardCommitment {
                        main_commit: [0u8; 32].into(),
                        permutation_commit: Some([0u8; 32].into()),
                    },
                    opened_values: SCShardOpenedValues {
                        chips: vec![],
                        _field: core::marker::PhantomData,
                    },
                    opening_proof: RootOpeningProof {
                        stack_log_height: Some(0),
                        sumcheck_transcript: SumcheckInstanceProof { uni_polys: vec![] },
                        iopp_oracles: vec![],
                        ood_values: vec![],
                        iopp_queries: vec![],
                        round_iopp: None,
                        query_openings: BasefoldInputProof::from_per_query(vec![]),
                        grinding_batching_witness: vec![],
                        grinding_query_witness: vec![],
                        iopp_pruned: None,
                        stacking_reduction: None,
                        final_poly: vec![],
                    },
                    sumcheck_proof: SumcheckProof { unipolys: vec![] },
                    dimensions: vec![],
                    chip_ordering: HashMap::new(),
                    public_values: vec![],
                };

                let reduce_vk = SCStarkVerifyingKey {
                    commit: [0u8; 32].into(),
                    pc_start: SCField::zero(),
                    chip_information: vec![],
                    chip_ordering: HashMap::new(),
                    program_boundary: dt_stark::global_d11::ProgramImageBoundaryV1::Infinity,
                    owner_registry: dt_stark::global_d11::BoundaryOwnerRegistryV2::new(vec![])
                        .expect("empty recursion owner registry is valid"),
                    global146_identity: dt_stark::global_d11::GLOBAL146_COMPOSITE_IDENTITY,
                    constraints_map: HashMap::new(),
                };

                let reduce_proof = Box::new(DTReduceProof { vk: reduce_vk, proof: shard_proof });
                DTProofWithPublicValues {
                    proof: DTProof::Compressed(reduce_proof),
                    public_values,
                    dt_version,
                    tee_proof: None,
                }
            }
            DTProofMode::Shrink => {
                let shard_proof = SCShardProof {
                    commitment: SCShardCommitment {
                        main_commit: [SCField::zero(); 8].into(),
                        permutation_commit: Some([SCField::zero(); 8].into()),
                    },
                    opened_values: SCShardOpenedValues {
                        chips: vec![],
                        _field: core::marker::PhantomData,
                    },
                    opening_proof: InnerOpeningProof {
                        stack_log_height: Some(0),
                        sumcheck_transcript: SumcheckInstanceProof { uni_polys: vec![] },
                        iopp_oracles: vec![],
                        ood_values: vec![],
                        iopp_queries: vec![],
                        round_iopp: None,
                        // [D6-N6] BasefoldInputProof wrapper: empty per_query, no pruned.
                        query_openings: BasefoldInputProof::from_per_query(vec![]),
                        grinding_batching_witness: vec![],
                        grinding_query_witness: vec![],
                        iopp_pruned: None,
                        stacking_reduction: None,
                        final_poly: vec![],
                    },
                    sumcheck_proof: SumcheckProof { unipolys: vec![] },
                    dimensions: vec![],
                    chip_ordering: HashMap::new(),
                    public_values: vec![],
                };

                let reduce_vk = SCStarkVerifyingKey {
                    commit: [SCField::zero(); 8].into(),
                    pc_start: SCField::zero(),
                    chip_information: vec![],
                    chip_ordering: HashMap::new(),
                    program_boundary: dt_stark::global_d11::ProgramImageBoundaryV1::Infinity,
                    owner_registry: dt_stark::global_d11::BoundaryOwnerRegistryV2::new(vec![])
                        .expect("empty recursion owner registry is valid"),
                    global146_identity: dt_stark::global_d11::GLOBAL146_COMPOSITE_IDENTITY,
                    constraints_map: HashMap::new(),
                };

                let reduce_proof = Box::new(DTReduceProof { vk: reduce_vk, proof: shard_proof });
                DTProofWithPublicValues {
                    proof: DTProof::Shrink(reduce_proof),
                    public_values,
                    dt_version,
                    tee_proof: None,
                }
            }
            DTProofMode::Plonk => DTProofWithPublicValues {
                proof: DTProof::Plonk(PlonkBn254Proof {
                    public_inputs: [
                        pk.vk.hash_bn254().as_canonical_biguint().to_string(),
                        public_values.hash_bn254().to_string(),
                    ],
                    encoded_proof: String::new(),
                    raw_proof: String::new(),
                    plonk_vkey_hash: [0; 32],
                }),
                public_values,
                dt_version,

                tee_proof: None,
            },
            DTProofMode::Groth16 => DTProofWithPublicValues {
                proof: DTProof::Groth16(Groth16Bn254Proof {
                    public_inputs: [
                        pk.vk.hash_bn254().as_canonical_biguint().to_string(),
                        public_values.hash_bn254().to_string(),
                    ],
                    encoded_proof: String::new(),
                    raw_proof: String::new(),
                    groth16_vkey_hash: [0; 32],
                }),
                public_values,
                dt_version,

                tee_proof: None,
            },
        }
    }
}

#[cfg(test)]
mod tests {
    #![allow(clippy::print_stdout)]

    use super::*;

    #[test]
    fn test_plonk_proof_bytes() {
        let plonk_proof = DTProofWithPublicValues {
            proof: DTProof::Plonk(PlonkBn254Proof {
                encoded_proof: "ab".to_string(),
                plonk_vkey_hash: [0; 32],
                public_inputs: [String::new(), String::new()],
                raw_proof: String::new(),
            }),
            public_values: DTPublicValues::new(),
            dt_version: String::new(),
            tee_proof: None,
        };
        let expected_bytes = [vec![0, 0, 0, 0], hex::decode("ab").unwrap()].concat();
        assert_eq!(plonk_proof.bytes(), expected_bytes);
    }

    #[test]
    fn test_groth16_proof_bytes() {
        let groth16_proof = DTProofWithPublicValues {
            proof: DTProof::Groth16(Groth16Bn254Proof {
                encoded_proof: "ab".to_string(),
                groth16_vkey_hash: [0; 32],
                public_inputs: [String::new(), String::new()],
                raw_proof: String::new(),
            }),
            public_values: DTPublicValues::new(),
            dt_version: String::new(),
            tee_proof: None,
        };
        let expected_bytes = [vec![0, 0, 0, 0], hex::decode("ab").unwrap()].concat();
        assert_eq!(groth16_proof.bytes(), expected_bytes);
    }

    #[test]
    fn test_mock_plonk_proof_bytes() {
        let mock_plonk_proof = DTProofWithPublicValues {
            proof: DTProof::Plonk(PlonkBn254Proof {
                encoded_proof: String::new(),
                plonk_vkey_hash: [0; 32],
                public_inputs: [String::new(), String::new()],
                raw_proof: String::new(),
            }),
            public_values: DTPublicValues::new(),
            dt_version: String::new(),
            tee_proof: None,
        };
        assert_eq!(mock_plonk_proof.bytes(), Vec::<u8>::new());
    }

    #[test]
    fn test_mock_groth16_proof_bytes() {
        let mock_groth16_proof = DTProofWithPublicValues {
            proof: DTProof::Groth16(Groth16Bn254Proof {
                encoded_proof: String::new(),
                groth16_vkey_hash: [0; 32],
                public_inputs: [String::new(), String::new()],
                raw_proof: String::new(),
            }),
            public_values: DTPublicValues::new(),
            dt_version: String::new(),
            tee_proof: None,
        };
        assert_eq!(mock_groth16_proof.bytes(), Vec::<u8>::new());
    }

    #[test]
    #[should_panic(
        expected = "Proof type Core is not supported for onchain verification. Only Plonk and Groth16 proofs are verifiable onchain"
    )]
    fn test_core_proof_bytes_unimplemented() {
        let core_proof = DTProofWithPublicValues {
            proof: DTProof::Core(vec![]),
            public_values: DTPublicValues::new(),
            dt_version: String::new(),
            tee_proof: None,
        };
        println!("{:?}", core_proof.bytes());
    }

    #[test]
    fn test_deser_backwards_compat() {
        let round_trip = DTProofWithPublicValues {
            proof: DTProof::Core(vec![]),
            public_values: DTPublicValues::new(),
            dt_version: String::new(),
            tee_proof: None,
        };

        let round_trip_bytes = bincode::serialize(&round_trip).unwrap();

        bincode::deserialize::<DTProofWithPublicValues>(&round_trip_bytes).unwrap();

        let _ = ProofFromNetwork {
            proof: DTProof::Core(vec![]),
            public_values: DTPublicValues::new(),
            dt_version: String::new(),
        };

        let _ = bincode::deserialize::<ProofFromNetwork>(&round_trip_bytes).unwrap();
    }
}
